<?php declare(strict_types=1);require __DIR__.'/includes/config.php';require __DIR__.'/includes/live.php';require __DIR__.'/includes/shell.php';$uid=ir_current_user_id();$term=trim((string)($_GET['q']??''));$like='%'.$term.'%';$groups=[];if($term!==''){try{$q=$pdo->prepare('SELECT id,jmeno_kod,latinsky_nazev FROM wp_ir2_zvirata WHERE user_id=? AND (jmeno_kod LIKE ? OR latinsky_nazev LIKE ?) LIMIT 15');$q->execute([$uid,$like,$like]);$groups['Zvířata']=array_map(fn($r)=>['animal.php?id='.$r['id'],$r['jmeno_kod'],$r['latinsky_nazev']],$q->fetchAll()?:[]);}catch(Throwable){}if(ir_table_exists($pdo,'wp_ir2_contacts')){$q=$pdo->prepare('SELECT id,name,type FROM wp_ir2_contacts WHERE user_id=? AND (name LIKE ? OR email LIKE ? OR phone LIKE ?) LIMIT 15');$q->execute([$uid,$like,$like,$like]);$groups['Adresář']=array_map(fn($r)=>['contacts.php?edit='.$r['id'],$r['name'],$r['type']],$q->fetchAll()?:[]);}if(ir_table_exists($pdo,'wp_ir2_documents')){$q=$pdo->prepare('SELECT id,title,category FROM wp_ir2_documents WHERE user_id=? AND (title LIKE ? OR category LIKE ? OR body_cs LIKE ? OR body_en LIKE ? OR body_de LIKE ?) LIMIT 15');$q->execute([$uid,$like,$like,$like,$like,$like]);$groups['Dokumenty']=array_map(fn($r)=>['documents.php?edit='.$r['id'],$r['title'],$r['category']],$q->fetchAll()?:[]);}try{$q=$pdo->prepare('SELECT id,nazev_ukolu,kategorie FROM wp_ir2_planovac WHERE user_id=? AND (nazev_ukolu LIKE ? OR poznamka LIKE ?) LIMIT 15');$q->execute([$uid,$like,$like]);$groups['Úkoly']=array_map(fn($r)=>['tasks.php',$r['nazev_ukolu'],$r['kategorie']??''],$q->fetchAll()?:[]);}catch(Throwable){}}ir_page_start('Globální vyhledávání','other');?><section class="panel glow-panel"><header class="panel-head"><div><span class="panel-kicker">GLOBAL SEARCH</span><h2><?= $term!==''?'Výsledky pro „'.ir_e($term).'“':'Hledat v IR Manageru' ?></h2></div></header><form action="search.php" class="form-grid"><label>Hledat zvíře, ID, kontakt, dokument nebo úkol<input autofocus name="q" value="<?=ir_e($term)?>"></label></form></section><?php foreach($groups as $name=>$rows):?><section class="panel glow-panel" style="margin-top:10px"><header class="panel-head"><h2><?=ir_e($name)?></h2></header><div class="dashboard-list"><?php foreach($rows as $r):?><a class="dashboard-list-row" href="<?=ir_e($r[0])?>"><?=ir_visual_icon('search')?><div><strong><?=ir_e($r[1])?></strong><small><?=ir_e($r[2])?></small></div><i>›</i></a><?php endforeach;if(!$rows):?><div class="empty-state small">Bez výsledků.</div><?php endif?></div></section><?php endforeach;ir_page_end();
